import {
  Native2,
  makeConnection2
} from "../chunks/repository-cache-tyytaxap.js";

// src/database/sqlite.workerd.ts
import { Context, Effect, Exit, Fiber, Layer, Scope, Semaphore } from "effect";
import { Reactivity } from "effect/reactivity";
import { SqlClient, Statement } from "effect/sql";
import { classifySqliteError, SqlError, UnknownError } from "effect/sql/SqlError";
var ATTR_DB_SYSTEM_NAME = "db.system.name";
var TypeId = "~@opencode/core/database/SqliteWorkerd";
var supportsTuningPragmas = false;
var supportsForeignKeyToggle = false;
var WorkerdTransaction = Context.Service("@opencode/core/database/SqliteWorkerdTransaction");
var transactionError = (message) => new SqlError({
  reason: new UnknownError({ cause: new Error(message), message, operation: "transaction" })
});
var makeWithTransaction = (storage, connection, semaphore) => (effect) => Effect.withFiber((fiber) => {
  const services = fiber.context;
  if (Context.getOption(services, WorkerdTransaction)._tag === "Some")
    return Effect.fail(transactionError("Nested transactions are not supported by Cloudflare Durable Object SQLite storage"));
  const effectWithTxn = Effect.provideContext(effect, Context.add(services, WorkerdTransaction, [connection, 0]));
  return semaphore.withPermits(1)(Effect.callback((resume) => {
    let interrupted = false;
    const promise = storage.transaction((txn) => new Promise((resolve) => {
      if (interrupted)
        return resolve();
      resume(Effect.onExit(effectWithTxn, (exit) => {
        if (Exit.isFailure(exit))
          txn.rollback();
        resolve();
        return Effect.promise(() => promise);
      }));
    })).catch((cause) => resume(Effect.fail(new SqlError({
      reason: classifySqliteError(cause, { message: "Failed transaction", operation: "transaction" })
    }))));
    return Effect.suspend(() => {
      interrupted = true;
      return Effect.promise(() => promise);
    });
  }));
});
var make = (options) => Effect.gen(function* () {
  const native = yield* Native2;
  const compiler = Statement.makeCompilerSqlite(options.transformQueryNames);
  const transformRows = options.transformResultNames ? Statement.defaultTransforms(options.transformResultNames).array : undefined;
  function* runIterator(query, params = []) {
    const cursor = native.sql.exec(query, ...params);
    const columns = cursor.columnNames;
    for (const row of cursor.raw()) {
      const record = {};
      for (let i = 0;i < columns.length; i++) {
        const value = row[i];
        record[columns[i]] = value instanceof ArrayBuffer ? new Uint8Array(value) : value;
      }
      yield record;
    }
  }
  const run = (query, params = []) => Effect.try({
    try: () => Array.from(runIterator(query, params)),
    catch: (cause) => new SqlError({
      reason: classifySqliteError(cause, { message: "Failed to execute statement", operation: "execute" })
    })
  });
  const runValues = (query, params = []) => Effect.try({
    try: () => Array.from(native.sql.exec(query, ...params).raw(), (row) => row.map((value) => value instanceof ArrayBuffer ? new Uint8Array(value) : value)),
    catch: (cause) => new SqlError({
      reason: classifySqliteError(cause, { message: "Failed to execute statement", operation: "execute" })
    })
  });
  const connection = makeConnection2(run, runValues, {});
  const semaphore = yield* Semaphore.make(1);
  const acquirer = semaphore.withPermits(1)(Effect.succeed(connection));
  const transactionAcquirer = Effect.uninterruptibleMask((restore) => {
    const fiber = Fiber.getCurrent();
    const scope = Context.getUnsafe(fiber.context, Scope.Scope);
    return Effect.as(Effect.tap(restore(semaphore.take(1)), () => Scope.addFinalizer(scope, semaphore.release(1))), connection);
  });
  const client = Object.assign(yield* SqlClient.make({
    acquirer,
    compiler,
    transactionAcquirer,
    transactionService: WorkerdTransaction,
    spanAttributes: [
      ...options.spanAttributes ? Object.entries(options.spanAttributes) : [],
      [ATTR_DB_SYSTEM_NAME, "sqlite"]
    ],
    transformRows
  }), {
    [TypeId]: TypeId,
    config: options,
    withTransaction: makeWithTransaction(native, connection, semaphore),
    transactionStatements: false
  });
  return client;
});
var nativeLayer = (config) => config.storage ? Layer.succeed(Native2, config.storage) : Layer.effect(Native2, Effect.die("workerd sqlite cannot open a database from a path; use Database.layerFromClient.pipe(Layer.provide(sqliteLayer({ storage })))"));
var clientLayer = (config) => Layer.effect(SqlClient.SqlClient, make(config));
var sqliteLayer = (config) => {
  const native = nativeLayer(config);
  return Layer.merge(native, clientLayer(config).pipe(Layer.provide(native))).pipe(Layer.provide(Reactivity.layer));
};
export {
  sqliteLayer,
  supportsForeignKeyToggle,
  supportsTuningPragmas
};
